/**
 * DeviceEvent — Domain entity representing an event generated by an
 * IoT device (e.g. panic button pressed, motion detected, device offline).
 *
 * Plain TypeScript interface — no classes, no decorators, no external deps.
 *
 * @see Requirements 37.5, 37.8, 37.9, 38.4, 38.5, 40.5, 40.6
 */

// ---------------------------------------------------------------------------
// Value types
// ---------------------------------------------------------------------------

export type DeviceEventType =
  | 'panic_button_pressed'
  | 'gate_open'
  | 'gate_closed'
  | 'motion_detected'
  | 'smoke_detected'
  | 'alarm_triggered'
  | 'smart_lock_opened'
  | 'cctv_motion_detected'
  | 'device_online'
  | 'device_offline'
  | 'battery_low'
  | 'emergency_alert'
  | 'smart_switch_toggled'
  | 'lighting_changed'
  | 'gate_open_too_long'
  | 'motion_detection_alert'
  | 'door_opened'
  | 'door_closed'
  | 'door_opened_during_window';

// ---------------------------------------------------------------------------
// Entity
// ---------------------------------------------------------------------------

export interface DeviceEvent {
  readonly id: string;
  readonly deviceId: string;
  readonly tenantId: string;
  readonly eventType: DeviceEventType;
  readonly payload: Record<string, unknown>;
  readonly isSharedSecurity: boolean;
  readonly processedAt: Date | null;
  readonly createdAt: Date;
}

// ---------------------------------------------------------------------------
// Input types
// ---------------------------------------------------------------------------

/** Data required to create a new device event record. */
export interface CreateDeviceEventInput {
  readonly deviceId: string;
  readonly eventType: DeviceEventType;
  readonly payload: Record<string, unknown>;
  readonly isSharedSecurity: boolean;
}
